#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
    ll t;
    cin >> t;
    while(t--){
        ll n;cin >> n;
        vector<ll> a(3*n);
        for(auto &x : a) cin >> x;
        sort(a.rbegin(),a.rend());
        vector<ll> pref(3*n+1,0);
        for(int i=0;i<3*n;i++){
            pref[i+1] = pref[i] + a[i];
        }
        ll ans = 0;
        for(int one = 0;one <= n;one++){
            auto score = [&](ll two) -> ll{
                ll three = n - one - two;
                ll first = one;
                ll second = first +  (2* two);
                ll third = second + (3 * three);
                return 6*pref[first] +  4*(pref[second]-pref[first]) + 3*(pref[third]-pref[second]);
            };
            ll low = 0;
            ll high=n-one;
            while(low < high){
                ll mid = low + (high - low)/2;
                if(score(mid+1) > score(mid)){
                    low= mid+1;
                }
                else{
                    high= mid;
                }
            }
            ans = max(ans,score(low));
        }
        cout << ans << "\n";
    }
}
